const base = m[1], leaf = m[2];
// A deleted retained message arrives as an empty payload: never act on it.
if (p === '') return null;
// Only follow the bridge that last said it's online, so a dead board's
// retained leftovers (or another bridge on the same broker) can't hijack the flow.
if (leaf === 'status') {
  node.status({fill: p === 'online' ? 'green' : 'red', shape:'dot', text: base + ': ' + p});
  if (p === 'online') flow.set('fjx7_base', base);
  else if (flow.get('fjx7_base') === base) flow.set('fjx7_base', undefined);
  return null;
}
if (base !== flow.get('fjx7_base')) return null;
const MODES = ['cool','heat','heat_cool','fan_only','dry'];
const AP = ['4A','5A','6A','7A','Unlimited'];
const FANS = ['auto','low','medium','high','Turbo'];
const out = [null,null,null,null,null];
// Remember what the AC last reported, so the command side can ignore echoes.
switch (leaf) {
  case 'status':
    node.status({fill: p === 'online' ? 'green' : 'red', shape:'dot', text: base + ': ' + p});
    return null;
  case 'climate/ac/mode/state': {
    flow.set('fjx7_state_mode', p);
    out[0] = {payload: {'SwitchableOutput/output_1/State': p === 'off' ? 0 : 1}};
    const i = MODES.indexOf(p);
    if (i >= 0) { flow.set('fjx7_last_mode', p); out[1] = {payload: {'SwitchableOutput/output_1/Dimming': i}}; }
    break;
  }
  case 'climate/ac/target_temperature/state':
    if (!isNaN(parseFloat(p))) flow.set('fjx7_state_target', parseFloat(p));
    if (!isNaN(parseFloat(p))) out[2] = {payload: {'SwitchableOutput/output_1/Dimming': parseFloat(p)}};
    break;
  case 'climate/ac/current_temperature/state':
    if (!isNaN(parseFloat(p))) out[2] = {payload: {'SwitchableOutput/output_1/Measurement': parseFloat(p)}};
    break;
  case 'climate/ac/fan_mode/state': {
    flow.set('fjx7_state_fan', p);
    const i = FANS.indexOf(p);
    if (i >= 0) out[4] = {payload: {'SwitchableOutput/output_1/Dimming': i}};
    break;
  }
  case 'select/adaptive_power/state': {
    flow.set('fjx7_state_ap', p);
    const i = AP.indexOf(p);
    if (i >= 0) out[3] = {payload: {'SwitchableOutput/output_1/Dimming': i}};
    break;
  }
}
// Stamp which controls we just updated from the AC: anything those controls
// emit in the next 1.5 s is an echo of this update, not a person.
const now = Date.now();
['power','mode','target','ap','fan'].forEach((k, i) => {
  if (!out[i]) return;
  const [key, v] = Object.entries(out[i].payload)[0];
  // Only a State/Dimming change can come back from the GX as a fake command.
  if (!/\/(State|Dimming)$/.test(key)) return;
  const recent = [].concat(flow.get('fjx7_inj_' + k) || []).filter(e => e && now - e.t < 1500);
  recent.push({t: now, v: String(v)});
  flow.set('fjx7_inj_' + k, recent);
});
return out;

// Turns a change made on the GX / VRM into an MQTT command for the bridge.
// Drops echoes: if the AC already reports this value, or we sent the same
// command in the last 3 s, send nothing. Stops GX <-> AC ping-pong loops.
function isEcho(ctrl) {
  // An echo is the GX handing back the exact value we just injected from the AC.
  // A different value inside the window is a person, so it must go through.
  const now = Date.now(), v = String(msg.payload);
  const recent = [].concat(flow.get('fjx7_inj_' + ctrl) || []);
  if (!recent.some(e => now - e.t < 1500 && e.v === v)) return false;
  node.status({fill:'grey', shape:'ring', text:'echo ignored ' + new Date().toLocaleTimeString()});
  return true;
}
function toBridge(suffix, payload, reported) {
  const base = flow.get('fjx7_base');
  if (!base) { node.warn('Bridge not seen yet (no MQTT state received) - command dropped'); return null; }
  if (reported !== undefined && String(reported) === String(payload)) return null;
  const key = 'fjx7_sent_' + suffix, last = flow.get(key), now = Date.now();
  if (last && last.v === String(payload) && now - last.t < 3000) return null;
  flow.set(key, {v: String(payload), t: now});
  node.status({fill:'green', shape:'dot', text:'sent ' + payload + ' ' + new Date().toLocaleTimeString()});
  return {topic: base + '/' + suffix, payload: payload};
}
if (isEcho('power')) return null;
const on = Number(msg.payload) === 1;
const cur = flow.get('fjx7_state_mode');
if (cur !== undefined && (cur !== 'off') === on) return null; // already in that state
const mode = on ? (flow.get('fjx7_last_mode') || 'cool') : 'off';
return toBridge('climate/ac/mode/command', mode);

