const t = Number(msg.payload);
if (isNaN(t)) return null;
const want = Math.min(31, Math.max(16, t));
// The GX temperature control is a slider: dragging or tapping it fires every
// value on the way. Wait until it has been still for 0.7 s, then send only
// where it ended up, so the AC gets one command (and one beep).
clearTimeout(context.get('settle'));
context.set('settle', setTimeout(() => {
  context.set('settle', undefined);
